-- ════════════════════════════════════════════════════════════════════════════
--  LAS ZONAS DE RECOLECCIÓN: un camión por zona.
--
--  Generado por `maxware-tools/zonas-armar-migracion.mjs` desde lo que calcula
--  `sectorizar-parroquia.mjs`. ⛔ NO SE EDITA A MANO: si hay que cambiar el
--  reparto, se vuelve a correr el sectorizador y se regenera este archivo. Dos
--  copias del mismo reparto se desincronizan.
--  [[norma-dos-listas-a-mano-se-desincronizan]]
--
--  Reparto: Olegario Villalobos en 8 · Caracciolo Parra Pérez en 10
--  Generado: 2026-10-29T15:13:33.668Z
-- ════════════════════════════════════════════════════════════════════════════

-- ── 1 · El territorio ───────────────────────────────────────────────────────
create table if not exists zonas (
  parroquia  text     not null,
  zona       smallint not null,
  color      smallint not null,
  calles     int      not null,
  carga_m    int      not null,
  area_ha    int      not null,
  vecinos    smallint[] not null default '{}',
  anillos    jsonb    not null,
  centro     jsonb    not null,
  generado   timestamptz not null default now(),
  primary key (parroquia, zona)
);
comment on table zonas is $c$El territorio de cada camión dentro de una parroquia. `anillos` es [[[lat,lon],...],...]: el PRIMERO es el contorno y los demás son huecos (manzanas que le tocan al vecino), así que para saber si un punto está adentro se cuenta cuántos anillos lo contienen y vale si es IMPAR. Mismo formato de coordenadas que parroquias.poligono y el que espera Leaflet. `color` es 0..3: cuatro alcanzan porque dos zonas vecinas nunca comparten tono. El reparto lo calcula maxware-tools/sectorizar-parroquia.mjs; esta tabla NO se edita a mano.$c$;

-- ── 2 · Qué tramos le tocan ─────────────────────────────────────────────────
create table if not exists zona_calles (
  id        bigserial primary key,
  parroquia text     not null,
  zona      smallint not null,
  calle_id  bigint   references calles(id) on delete cascade,
  tramo     text,
  nombre    text,
  tipo      text,
  pases     smallint not null default 1,
  metros    int      not null,
  orden     smallint not null,
  geom      jsonb    not null,
  -- ⛔ La caja envolvente va en COLUMNAS, no se saca del jsonb al vuelo. Sin
  --    esto, buscar el tramo más cercano recorre los 942 tramos midiendo
  --    segmento por segmento: la primera versión ni siquiera terminó — el
  --    servidor cortó la conexión. Con la caja indexada quedan ~20 candidatos.
  la_min    double precision not null,
  la_max    double precision not null,
  lo_min    double precision not null,
  lo_max    double precision not null
);
comment on table zona_calles is $c$Los tramos de calle que le tocan a cada zona. ⛔ Una calle puede aparecer MÁS DE UNA VEZ y hasta en dos zonas distintas: las avenidas se cortan en tramos para poder repartir la carga (la Av. Universidad sola era el 35% de un sector). Por eso la llave es propia y no calle_id. `orden` es el número que el chofer ve en su hoja, de norte a sur — NO es el orden del recorrido, que nadie midió.$c$;
create index if not exists zona_calles_zona on zona_calles (parroquia, zona);
create index if not exists zona_calles_calle on zona_calles (calle_id);
create index if not exists zona_calles_caja on zona_calles (la_min, la_max, lo_min, lo_max);

-- ── 3 · Quién la hace, con fecha ────────────────────────────────────────────
create table if not exists zona_asignacion (
  id        uuid primary key default gen_random_uuid(),
  parroquia text     not null,
  zona      smallint not null,
  cam       text     not null,
  desde     date     not null default current_date,
  hasta     date,
  nota      text,
  creado    timestamptz not null default now(),
  creado_por text
);
comment on table zona_asignacion is $c$Qué camión hace cada zona, CON FECHA. `hasta` nulo = vigente. Asignación FIJA es una fila por zona y nada más; ROTATIVA es cerrar la fila (poner `hasta`) y abrir otra. En los dos casos queda el historial, que es lo único que después contesta «¿quién tenía la zona 5 el día que no se recogió?». ⛔ Por eso el camión NO es una columna de `zonas`: ahí se pisaría y no se podría auditar.$c$;
create index if not exists zona_asignacion_vig on zona_asignacion (parroquia, zona, desde desc);

-- ⛔ Dos camiones a la misma zona el mismo día es un error de carga, no una
--    opción. Y el mismo camión en dos zonas el mismo día, también.
create unique index if not exists zona_asignacion_una_por_zona
  on zona_asignacion (parroquia, zona) where hasta is null;
create unique index if not exists zona_asignacion_un_cam
  on zona_asignacion (parroquia, cam) where hasta is null;


